insert into `stock`.`other_value` (other_key,`name`,other_value,remark,visible_flag) select 'activity_monitoring_notification_token','客户活跃监测通知-机器人token','',null,0 from other_value where not exists (select other_key from other_value where other_key = 'activity_monitoring_notification_token')limit 1;
insert into `stock`.`other_value` (other_key,`name`,other_value,remark,visible_flag) select 'activity_monitoring_notification_chat_id','客户活跃监测通知-群组ID','',null,0 from other_value where not exists (select other_key from other_value where other_key = 'activity_monitoring_notification_chat_id')limit 1;
